import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult

def validate_invoice_fields(document_content: bytes, required_fields: list[str]) -> dict[str, dict | None]:
    """
    Validates required structured fields and confidence scores from an invoice document
    using Azure Document Intelligence.

    Args:
        document_content: The content of the invoice document as bytes.
        required_fields: A list of field names to validate (e.g., ["VendorName", "InvoiceTotal"]).

    Returns:
        A dictionary mapping each required field name to its extracted value and confidence,
        or None if the field was not found.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY must be set in environment variables.")

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-invoice", document_content, content_type="application/octet-stream"
    )
    result: AnalyzeResult = poller.result()

    extracted_data = {}
    if result.documents:
        # Assuming we only care about the first detected document for simplicity
        invoice = result.documents[0]
        for field_name in required_fields:
            if field_name in invoice.fields:
                field = invoice.fields[field_name]
                extracted_value = None
                if field.value_type == "string":
                    extracted_value = field.content
                elif field.value_type == "number":
                    extracted_value = field.value_number
                elif field.value_type == "date":
                    extracted_value = field.value_date
                elif field.value_type == "currency":
                    if field.value_currency:
                        extracted_value = {
                            "amount": field.value_currency.amount,
                            "currency_symbol": field.value_currency.currency_symbol,
                        }
                    else:
                        extracted_value = None
                # Add more value types as needed (e.g., array, object for line items)
                # For this task, we focus on scalar values or simple currency.

                extracted_data[field_name] = {
                    "value": extracted_value,
                    "confidence": field.confidence
                }
            else:
                extracted_data[field_name] = None

    return extracted_data
